def semver_sort(versions):
    def parse(v):
        # remove build metadata
        core = v.split('+', 1)[0]
        # find prerelease starting at first '-'
        dash_idx = core.find('-')
        if dash_idx == -1:
            main = core
            prerelease = None
        else:
            main = core[:dash_idx]
            prerelease = core[dash_idx+1:]

        major, minor, patch = (int(x) for x in main.split('.'))

        if prerelease is None:
            has_pre = 1  # no prerelease sorts after
            pre_list = []
        else:
            has_pre = 0
            ids = prerelease.split('.')
            pre_list = []
            for ident in ids:
                if ident.isdigit():
                    pre_list.append((0, int(ident)))
                else:
                    pre_list.append((1, ident))

        return (major, minor, patch, has_pre, pre_list)

    return sorted(versions, key=parse)

